// Adapted from OpenTerminal web/lib/symbol.ts (MIT, see LICENSES/OpenTerminal-MIT.txt in the repository root): only the
// demo instruments are valid. They are fictional (generated by terminal_demo.generate), not real tickers.
export const SYMBOLS = ["DEMO-A", "DEMO-B", "DEMO-C", "DEMO-D"] as const;

/** Short descriptions shown in the command palette (the data file carries the same names). */
export const SYMBOL_NAMES: Record<string, string> = {
  "DEMO-A": "Simulated broad index-like instrument",
  "DEMO-B": "Simulated higher-volatility growth-like instrument",
  "DEMO-C": "Simulated lower-volatility instrument",
  "DEMO-D": "Simulated small-cap-like instrument",
};

/** Uppercases and trims input; null unless it is one of the demo instruments. */
export function normalizeSymbol(raw: string): string | null {
  const s = raw.trim().toUpperCase();
  return (SYMBOLS as readonly string[]).includes(s) ? s : null;
}
